export type Role = "me" | "gilbert" | "mccauley" | "gagnon" | "gifford" | "all";

export interface AgendaItem {
  time: string;
  duration: string;
  activity: string;
  description: string;
  lead: Role;
  slides?: string;
}

export interface FacilitatorNote {
  slide: string;
  role: Role;
  note: string;
}

export interface Resource {
  title: string;
  description: string;
  url: string;
  type: "pdf" | "slides" | "doc" | "video" | "archive";
}

// GitHub Pages serves the packaged PLC files from the repository's assets folder,
// while the managed website continues to use its permanent storage paths.
const plcDownloadAsset = (filename: string, storagePath: string) =>
  import.meta.env.BASE_URL === "/nbhs-science/" ? `assets/plc/${filename}` : storagePath;

