    sessionInfo: { overview: "This opening bridge PLC gives science teachers protected time to plan a real upcoming lesson with colleagues. The focus is practical: clarify the student learning goal and task, prepare materials, connect the lesson to the course plan, and establish shared educator roles before instruction begins.", whyItMatters: "Collaborative planning is strongest when teachers work from the same lesson materials and make their instructional decisions together before students encounter the task.", learningArc: "Session 1 of 5. This bridge session builds a shared planning foundation before the department’s September 8–14 Lesson Internalization deep dives.", teacherTakeaways: ["One shared plan for an upcoming lesson.", "Clearer materials and educator-role preparation.", "A starting point for Friday’s curriculum-alignment work."] },
