    sessionInfo: { overview: "Teams use a small anonymous evidence set to identify a shared pattern in student learning and how student thinking was made visible. The work then connects that pattern to participation and feedback that prompt a next student action.", whyItMatters: "A shared evidence review helps teams move from isolated impressions to a documented pattern. It also makes participation and feedback concrete: both should be connected to evidence and help students explain, model, revise, compare, apply, or otherwise move their thinking forward.", learningArc: "Continuation 2 of 6 — The evidence captured after instruction becomes a shared learning-and-participation pattern that teams will use to plan the next student action on September 21.", teacherTakeaways: ["One shared learning-and-participation pattern.", "Evidence that supports the pattern.", "An anticipated feedback prompt or participation routine for the next lesson."] },
